   501	_PUBLIC_ void ndr_print_string_array(struct ndr_print *ndr, const char *name, const char **a)
   502	{
   503	        uint32_t count;
   504	        uint32_t i;
   505	
   506	        for (count = 0; a && a[count]; count++) {}
   507	
   508	        ndr->print(ndr, "%s: ARRAY(%d)", name, count);
   509	        ndr->depth++;
   510	        for (i=0;i<count;i++) {
   511	                char *idx=NULL;
   512	                if (asprintf(&idx, "[%d]", i) != -1) {
   513	                        ndr_print_string(ndr, idx, a[i]);
   514	                        free(idx);
   515	                }
   516	        }
   517	        ndr->depth--;
   518	}
